INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('BAS-0040', 'BAS', 'BAS-0040 : System attribute is possible to set at "SYSTEM" factory.', 'BAS-0040 : 시스템 속성은 "SYSTEM" 공장내에서만 변경 가능합니다.', 'BAS-0040 : System Attribut kann nur im "SYSTEM" FAB geandert werden.', 'ADMIN', '20120502112524', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('BAS-0041', 'BAS', 'BAS-0041 : This attribute is a system attribute. You can not delete it.', 'BAS-0041 : 이 속성은 시스템 속성입니다. 그래서 삭제할수 없습니다.', 'BAS-0041 : Dieses Attribut ist ein System-Attribut. Sie konnen es nicht loschen.', 'ADMIN', '20120502112604', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('BAS-0042', 'BAS', 'BAS-0042 : Invalid template xml directory path, Please check [MESplusDocTempDir] in MESplus.ini file.','BAS-0042 : 유효하지 않은 디렉토리입니다. MESplus.ini파일의 [MESplusDocTempDir]을 확인해 주십시요.','BAS-0042 : Ungultiges Verzeichnis. Bitte uberprufen Sie [MESplusDocTempDir] in der MESplus.ini Datei.','ADMIN','20050620163452',' ',' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('BAS-0043', 'BAS', 'BAS-0043 : This template already used.', 'BAS-0043 : 이 템플릿은 이미 사용중입니다.', 'BAS-0043 : Diese Vorlage wird bereits genutzt.','ADMIN', '20081201010101', 'ADMIN', '20081217170645');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('BAS-0044', 'BAS', 'BAS-0044 : This menu does not exist in menu group.','BAS-0044 : 이 메뉴는 메뉴 그룹에 속해있지 않습니다.','BAS-0044 : Dieses Menu fehlt in der Befehlsubersicht.','ADMIN','20120522172450',' ',' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('BAS-0045', 'BAS', 'BAS-0045 : Does not exist menu group id','BAS-0045 : 존재하지 않는 메뉴 그룹입니다.','BAS-0045 : Diese Menu-Gruppen ID existiert nicht.','ADMIN','20120522172512',' ',' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0000', 'SPM', 'SPM-0000 : This  process step number is not supported. Please check the process step number.', 'SPM-0000 : 지원되지 않는 STEP입니다. 다시 확인 하십시요.', 'SPM-0000 : Dieser STEP wird nicht unterstutzt. Bitte um erneute Uberprufung.', 'ADMIN', '20120420095150', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0001', 'SPM', 'SPM-0001 : A required field is empty. Please enter a valid value.', 'SPM-0001 : 이 항목은 필요한 필드 입니다. 입력 바랍니다.', 'SPM-0001 : Dieser Eintrag ist erforderlich. Bitte um Eingabe.', 'ADMIN', '20120420095205', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0002', 'SPM', 'SPM-0002 : This Specification already exists.', 'SPM-0002 : 이 제조명세는 이미 존재합니다.', 'SPM-0002 : Diese Fertigungsspezifikationen existieren bereits.', 'ADMIN', '20120420095707', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0003', 'SPM', 'SPM-0003 : This Specification Version already exists.', 'SPM-0003 : 이 제조명세 버전은 이미 존재합니다.', 'SPM-0003 : Diese Version der Fertigungsspezifikation existiert bereits.', 'ADMIN', '20120420095323', 'ADMIN', '20120420095717');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0004', 'SPM', 'SPM-0004 : Fatal database error is occurred. Please contact admin person.', 'SPM-0004 : Database 작업중 오류가 발생 하였습니다. 관리자에게 문의 바랍니다.', 'SPM-0004 : Ein Datenbankfehler ist aufgetreten. Bitte kontaktieren Sie den Administrator.', 'ADMIN', '20120420095528', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0005', 'SPM', 'SPM-0005 : Specification does not exist.', 'SPM-0005 : 제조명세가 존재하지 않습니다.', 'SPM-0005 : Es existieren keine Fertigungsspezifikationen.', 'ADMIN', '20120420100122', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0006', 'SPM', 'SPM-0006 : Specification version does not exist.', 'SPM-0006 : 제조명세의 버전이 존재하지 않습니다.', 'SPM-0006 : Es existiert keine Version der Fertigungsspezifikation.', 'ADMIN', '20120420100149', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0007', 'SPM', 'SPM-0007 : Cannot delete approved or released Specification version.', 'SPM-0007 : 승인 혹은 배포된 제조명세의 버전은 삭제할 수 없습니다.', 'SPM-0007 : Bereits genehmigte oder verteilte Version der Fertigungsspezifikation kann nicht geloscht werden.', 'ADMIN', '20120420100433', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0008', 'SPM', 'SPM-0008 : The end time is less than the start time. Please check the start time.', 'SPM-0008 : 시작시간은 종료시간보다 작아야 합니다. 시작시간을 확인해 주십시오.', 'SPM-0008 : Die Startzeit muss kleiner als die Endzeit sein. Bitte uberprufen Sie die Startzeit.', 'ADMIN', '20120420100452', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0009', 'SPM', 'SPM-0009 : Specification character relation does not exist.', 'SPM-0009 : 제조명세에 대한 캐릭터 관계가 존재하지 않습니다.', 'SPM-0009 : Charakterbeziehung der Herstellungsspezifikationen existiert nicht.', 'ADMIN', '20120420100642', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0010', 'SPM', 'SPM-0010 : Can not create directory to save file attached to specification version.', 'SPM-0010 : 제조명세에 대한 첨부파일을 저장하기 위한 디렉토리를 생성할 수 없습니다.', 'SPM-0010 : Ein Verzeichnis kann nicht erstellt werden, um die angehangte Datei der Fertigungsspezifikationen zu speichern.', 'ADMIN', '20120427135759', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0011', 'SPM', 'SPM-0011 : A fatal error occurred during searching for a file attached to specification.', 'SPM-0011 : 제조명세에 대한 첨부파일을 찾는중 오류가 발생 하였습니다.', 'SPM-0011 : Ein Fehler ist aufgetreten wahrend der Suche nach der angehangten Datei der Fertigungsspezifikationen.', 'ADMIN', '20120427135828', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0012', 'SPM', 'SPM-0012 : Cannot update approved or released Specification version.', 'SPM-0012 : 이미 승인 또는 배포된 제조명세 버전은 변경할 수 없습니다.', 'SPM-0012 : Bereits genehmigte oder verteilte Version der Fertigungsspezifikation kann nicht geandert werden.', 'ADMIN', '20120503132816', 'ADMIN', '20120503133125');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('SPM-0013', 'SPM', 'SPM-0013 : Too long file name. Maximum file name is 50 bytes. Please reduce attached file name length.', 'SPM-0013 : 첨부파일명이 너무 깁니다. 최대 크기는 50 Byte 이므로 파일명을 변경해 주시기 바랍니다.', 'SPM-0013 : Dateiname ist zu lang. Bitte reduzieren sie den beigefugten Dateinamen bis maximal 50 bytes.', 'ADMIN', '20120503184521', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0499', 'WIP', 'WIP-0499 : This test program ID  is already exist.', 'WIP-0499 : 이 Test Program ID는 이미 존재 합니다.', 'WIP-0499 : Diese Testprogramm ID existiert bereits.', 'ADMIN', '20120418163609', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0500', 'WIP', 'WIP-0500 : This test program ID is not exist.', 'WIP-0500 : 이 Test Program ID는 존재하지 않습니다.', 'WIP-0500 : Diese Testprogramm ID ist nicht vorhanden.', 'ADMIN', '20120418190556', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0501', 'WIP', 'WIP-0501 : Transaction target Lot ID does not exist', 'WIP-0501 : 트랜젝션을 위한 대상 Lot 가 존재하지 않습니다.', 'WIP-0501 : Transaktionsziel des Los ID existiert nicht.', 'ADMIN', '20120424132909', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0502', 'WIP', 'WIP-0502 : BIN Setup does not exist for this Lot.', 'WIP-0502 : 선택된 Lot에 맞는 BIN Setup이 존재하지 않습니다.', 'WIP-0502 : BIN Setup existiert nicht fur dieses Los.', 'ADMIN', '20120419105426', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0503', 'WIP', 'WIP-0503 : Lot never into this operation.', 'WIP-0503 : 해당 공정에서 진행한 이력이 없습니다.', 'WIP-0503 : Keine Aufzeichnungen der entsprechenden Operation vorhanden.', 'ADMIN', '20120419105426', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0504', 'WIP', 'WIP-0504 : System can not generate Lot ID based on Generation Rule.', 'WIP-0504 : 해당 Generation Rule에 의한 Generate에 실패 했습니다.', 'WIP-0504 : System kann nicht Los ID generieren anhand der Generation Rule.', 'ADMIN', '20120419105426', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0505', 'WIP', 'WIP-0505 : Generate Rule does not exist.', 'WIP-0505 : 해당 Generation Rule이 존재하지 않습니다.', 'WIP-0505 : Entsprechende "Generate Rule" existiert nicht.', 'ADMIN', '20120419105426', ' ', ' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0506', 'WIP', 'WIP-0506 : Def_code already exists.','WIP-0506 :  Def_code가 이미 존재 합니다.','WIP-0506 : Def_code existiert bereits.','ADMIN','20120426163729',' ',' ');
INSERT INTO MMSGMSGDEF (MSG_ID,MSG_GRP,MSG_1,MSG_2,MSG_3,CREATE_USER_ID,CREATE_TIME,UPDATE_USER_ID,UPDATE_TIME) VALUES ('WIP-0507', 'WIP', 'WIP-0507 : Rule is not connected to the MFO.','WIP-0507 : Rule이 MFO와 연결되지 않았습니다.','WIP-0507 : Rule ist nicht mit MFO verbunden.','ADMIN','20120426163957',' ',' ');
